import {EVENTS} from './data.js';
import {illustration} from './art.js';
import {normalizeCode,deal,sorted,scoreOrder,moveCard,yearLabel,gameKey} from './core.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
let config={code:normalizeCode(params.get('game'))||'001',players:params.get('players')==='3'?3:2,seat:0,mode:params.get('mode')==='guess'?'guess':'timeline'};
let screen='setup',session=null,dragFrom=null,libraryQuery='',category='All';
const lookup=id=>EVENTS.find(e=>e.id===id);
$('.count').textContent=EVENTS.length;
const icon={timeline:'<svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M5 20h30" stroke="currentColor" stroke-width="2"/><rect x="7" y="9" width="8" height="14" rx="2" fill="currentColor"/><rect x="24" y="17" width="8" height="14" rx="2" fill="currentColor"/><path d="m31 16 4 4-4 4" stroke="currentColor" stroke-width="2"/></svg>',guess:'<svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M9 8h22a4 4 0 0 1 4 4v13a4 4 0 0 1-4 4H18l-8 6v-6H9a4 4 0 0 1-4-4V12a4 4 0 0 1 4-4Z" stroke="currentColor" stroke-width="2"/><path d="M15 16c0-7 12-6 10 0-1 2-5 2-5 6m0 2v2" stroke="currentColor" stroke-width="2"/></svg>'};

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function modal(content){$('#modal-content').innerHTML=content;$('#modal').showModal();}
function showHelp(){modal(`<p class="eyebrow">HOW TO PLAY</p><h2>Two games. Five cards each.</h2><div class="help-section"><h3>Set up together</h3><ol><li>Choose the same game code (001–100), player count and game mode.</li><li>Choose a different player number on each device. The code always deals the same hands, with no duplicates between players.</li><li>Play together in person or on a call. You can also pass one device between players.</li></ol><p class="small-note">The code shares the deal. Moves and scores are saved on this device only; they do not sync between devices.</p></div><div class="help-section"><h3>01 / Put it in order</h3><p>Each player arranges their five cards from oldest to newest. Drag cards or use the arrow buttons. Say why: <span lang="es">«Creo que la rueda apareció antes que el papel».</span></p><p>Check once everyone is ready. You get one point per card in the correct position (up to 5). The first check is your recorded score. Compare scores; the highest score wins. Equal scores are a draw.</p></div><div class="help-section"><h3>02 / Describe & guess</h3><p>The reader sees a Spanish clue, with the invention and date hidden. Read or paraphrase it. The named guesser answers aloud, then the reader reveals the card and marks Correct or Pass. Do not read the answer before the guess.</p><p>Each player reads five clues. With 2 players, read for each other. With 3, the next player guesses (1 → 2 → 3 → 1). A correct answer earns the guesser one point. Compare scores after all hands.</p></div><button class="primary wide" data-action="close-modal">Got it</button>`);}
function languageHelp(){modal(`<p class="eyebrow">LANGUAGE REFERENCE</p><h2>Before it existed…</h2><div class="help-section"><h3>Imperfect / the situation before</h3><p lang="es">Antes de este invento, la gente no <strong>podía</strong> conservar sus palabras fácilmente. Muchas personas <strong>dependían</strong> de la memoria.</p><p class="small-note">Use the imperfect for past situations, habits and limitations: podía, tenía, era, vivía.</p></div><div class="help-section"><h3>Preterite / what changed</h3><p lang="es">La escritura <strong>permitió</strong> registrar información. Las personas <strong>empezaron</strong> a guardar sus ideas.</p><p class="small-note">Use the preterite for completed events and changes: inventó, descubrió, permitió, cambió.</p></div><div class="help-section"><h3>Talking about time</h3><div class="phrase-list" lang="es"><span>A principios del siglo XX</span><span>A mediados del siglo XX</span><span>A finales del siglo XX</span><span>En los años 20 / En la década de los 20</span><span>A principios de los años 50</span><span>A mediados de los años 50</span><span>A finales de los años 50</span><span>En 1939</span></div></div>`);}
function dateHelp(){modal(`<p class="eyebrow">THE DECK</p><h2>One date per milestone.</h2><p>This game uses one fixed reference year for each card, including events that developed over time or have debated dates. Ancient dates are approximate game conventions, not exact historical claims.</p><p>Each answer includes a broader Spanish time expression and the reference year. The notes explain the specific milestone: for example, an experiment, a patent or a published discovery.</p><p>Several inventions had many contributors. The Wi-Fi card distinguishes the 1997 standard from Hedy Lamarr and George Antheil’s 1942 precursor. The DNA card describes the structure, with Rosalind Franklin’s contribution.</p><div class="source-list">${sorted(EVENTS).map(e=>`<a href="${esc(e.source)}" target="_blank" rel="noopener noreferrer"><span lang="es">${esc(e.title)}</span><span>${yearLabel(e.year)} ↗</span></a>`).join('')}</div>`);}
function cardDetail(id){const e=lookup(id);if(!e)return;modal(`<div class="detail-art">${illustration(e.id)}</div><p class="eyebrow">${esc(e.category)}</p><h2 lang="es">${esc(e.title)}</h2><div class="date-block" lang="es"><strong>${yearLabel(e.year)}</strong><span>${esc(e.approx)}</span></div><p class="person">${esc(e.person)}</p><div class="practice-block" lang="es"><span class="micro">BEFORE / IMPERFECT</span><p>${esc(e.before)}</p><span class="micro">WHAT CHANGED / PRETERITE</span><p>${esc(e.after)}</p></div><p class="small-note">${esc(e.note)}</p><a class="text-link" href="${esc(e.source)}" target="_blank" rel="noopener noreferrer">Historical source ↗</a>`);}

function previewCard(id,extra=''){const e=lookup(id);return `<div class="preview-card ${extra}"><div class="preview-art">${illustration(id)}</div><div class="preview-name" lang="es">${esc(e?.title||id)}</div><div class="preview-rule"><span>ANTES</span><i></i><span>DESPUÉS</span></div></div>`;}
function setup(){
  screen='setup';
  document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav==='play'));
  $('#app').innerHTML=`<section class="intro"><div class="intro-copy"><p class="eyebrow"><span class="tiny-line"></span> TWO GAMES · ONE HISTORICAL DECK</p><h1>Before <br>or <em>after?</em></h1><p class="intro-description">Put history in order. Or describe it and let someone guess.<br>Two games to practise the past in Spanish.</p><div class="intro-meta"><span>2–3 players</span><span>5 cards each</span><span>${EVENTS.length} illustrated milestones</span></div></div><div class="card-fan" aria-label="Illustrated cards from the deck">${previewCard('telescope','fan-left')}${previewCard('bulb','fan-middle')}${previewCard('airplane','fan-right')}<span class="fan-caption">Inventions · discoveries · everyday life</span><svg class="fan-doodle" viewBox="0 0 80 60" aria-hidden="true"><path d="M5 10q55-25 60 30m-12-5 12 10 8-16" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></div></section>
  <section class="setup-panel" aria-labelledby="setup-title"><div class="panel-heading"><h2 id="setup-title">Set up your game</h2><span class="micro">01 / CHOOSE A MODE</span></div><div class="mode-grid"><button class="mode-card ${config.mode==='timeline'?'selected':''}" data-mode="timeline" aria-pressed="${config.mode==='timeline'}"><span class="mode-icon">${icon.timeline}</span><span><span class="mode-number">GAME 01</span><strong>Put it in order</strong><span class="mode-description">Arrange your cards from oldest to newest.</span></span><span class="radio-dot"></span></button><button class="mode-card ${config.mode==='guess'?'selected':''}" data-mode="guess" aria-pressed="${config.mode==='guess'}"><span class="mode-icon">${icon.guess}</span><span><span class="mode-number">GAME 02</span><strong>Describe & guess</strong><span class="mode-description">Read the clue. Name the invention.</span></span><span class="radio-dot"></span></button></div>
  <div class="setup-controls"><div class="control-group code-group"><label for="game-code">Game code <span class="small-note">001–100</span></label><div class="code-input"><input id="game-code" inputmode="numeric" maxlength="3" value="${config.code}" autocomplete="off" aria-describedby="code-hint code-error"><button aria-label="Choose a random game code" data-action="random" title="Random code">⤨</button></div><p id="code-hint" class="small-note">Same code, same cards.</p><p id="code-error" class="error" role="alert"></p></div><fieldset class="control-group"><legend>Players</legend><div class="segmented">${[2,3].map(n=>`<button data-players="${n}" aria-pressed="${config.players===n}" class="${config.players===n?'active':''}">${n} players</button>`).join('')}</div><p class="small-note">Use the same count together.</p></fieldset><fieldset class="control-group"><legend>You are</legend><div class="segmented seat-select">${Array.from({length:config.players},(_,i)=>`<button data-seat="${i}" aria-pressed="${config.seat===i}" class="${config.seat===i?'active':''}">Player ${i+1}</button>`).join('')}</div><p class="small-note">Choose a different number each.</p></fieldset></div><div class="setup-bottom"><p><span class="status-dot"></span> Play together in person or on a call.<br><span class="small-note">No live sync. You can also pass one device.</span></p><button class="primary" data-action="start">Deal my cards <span aria-hidden="true">→</span></button></div></section><div class="below-setup"><button class="text-link" data-action="language">Past tenses & time expressions <span aria-hidden="true">↗</span></button><span>Dates stay hidden until the reveal.</span></div>`;
}
function readConfig(){const input=$('#game-code');if(!input)return true;const code=normalizeCode(input.value);if(!code){$('#code-error').textContent='Enter a code from 001 to 100.';input.setAttribute('aria-invalid','true');input.focus();return false;}config.code=code;input.value=code;$('#code-error').textContent='';input.removeAttribute('aria-invalid');return true;}
function persist(){try{localStorage.setItem(gameKey(config.code,config.players,config.mode),JSON.stringify(session));}catch{}}
function newSession(){return {version:1,orders:deal(EVENTS,config.code,config.players).map(h=>h.map(c=>c.id)),results:{},guess: Array.from({length:config.players},()=>({index:0,marks:[]}))};}
function validSaved(saved,fresh){return saved?.version===1&&Array.isArray(saved.orders)&&saved.orders.length===config.players&&saved.orders.every((h,i)=>Array.isArray(h)&&h.length===5&&JSON.stringify([...h].sort())===JSON.stringify([...fresh.orders[i]].sort()))&&saved.results&&typeof saved.results==='object'&&!Array.isArray(saved.results)&&Object.entries(saved.results).every(([seat,score])=>/^\d$/.test(seat)&&Number(seat)<config.players&&Number.isInteger(score)&&score>=0&&score<=5)&&Array.isArray(saved.guess)&&saved.guess.length===config.players&&saved.guess.every(g=>Number.isInteger(g.index)&&g.index>=0&&g.index<=5&&Array.isArray(g.marks)&&g.marks.length===g.index&&g.marks.every(m=>typeof m==='boolean'));}
function start(){if(!readConfig())return;const fresh=newSession();try{const saved=JSON.parse(localStorage.getItem(gameKey(config.code,config.players,config.mode)));session=validSaved(saved,fresh)?saved:fresh;}catch{session=fresh;}
  const url=new URL(location.href);url.search=new URLSearchParams({game:config.code,players:config.players,mode:config.mode});history.replaceState({},'',url);renderGame();window.scrollTo(0,0);
}
function gameHeader(){return `<div class="game-top"><button class="text-link" data-action="setup">← Game setup</button><div class="game-code-badge">GAME <strong>${config.code}</strong><span>· ${config.players} players</span><button data-action="share" title="Copy game link" aria-label="Copy game link">↗</button></div></div><div class="game-heading"><div><p class="eyebrow">${config.mode==='timeline'?'GAME 01 / TIMELINE':'GAME 02 / SPEAKING'}</p><h1>${config.mode==='timeline'?'Put it in order':'Describe & guess'}</h1></div><button class="secondary" data-action="language">Language reference ↗</button></div><div class="player-tabs" role="group" aria-label="Choose player">${Array.from({length:config.players},(_,i)=>`<button class="player-tab ${i===config.seat?'active':''}" data-switch="${i}"><span class="player-dot">${i+1}</span>Player ${i+1}${config.mode==='timeline'&&session.results[i]!==undefined?`<span class="tab-score">${session.results[i]}/5</span>`:''}${config.mode==='guess'&&session.guess[i].index===5?'<span class="tab-score">✓</span>':''}</button>`).join('')}</div>`;}
function timelineCard(id,i,revealed,solution){const e=lookup(id);const correct=sorted(session.orders[config.seat].map(lookup))[i].id===id;return `<article class="game-card ${revealed?(correct||solution?'correct':'incorrect'):''}" data-card-index="${i}" draggable="${!revealed}"><div class="card-position"><span>${String(i+1).padStart(2,'0')}</span><span>${revealed?(correct||solution?'✓':'↔'):'↔'}</span></div><button class="card-content" data-detail="${revealed?id:''}" ${!revealed?'disabled':''} aria-label="${revealed?'Read about '+esc(e.title):esc(e.title)}"><div class="card-art">${illustration(id)}</div><span class="card-category">${esc(e.category)}</span><h3 lang="es">${esc(e.title)}</h3>${revealed?`<div class="card-date" lang="es"><strong>${yearLabel(e.year)}</strong><span>${esc(e.approx)}</span></div>`:'<span class="hidden-date">Date hidden</span>'}</button>${!revealed?`<div class="card-moves"><button data-move="${i},${i-1}" ${i===0?'disabled':''} aria-label="Move ${esc(e.title)} earlier">← Earlier</button><button data-move="${i},${i+1}" ${i===4?'disabled':''} aria-label="Move ${esc(e.title)} later">Later →</button></div>`:'<div class="card-open">Read the story ↗</div>'}</article>`;}
function renderGame(solution=false){screen='game';if(config.mode==='guess'){renderGuess();return;}const result=session.results[config.seat];const revealed=result!==undefined;const hand=session.orders[config.seat];const allDone=Object.keys(session.results).length===config.players;
  $('#app').innerHTML=`<section class="game-view">${gameHeader()}<div class="board-instruction"><div><h2>Player ${config.seat+1}’s five cards</h2><p>${revealed?'Dates revealed. Open a card to read what changed.':'Drag the cards, or use the arrows. Keep the dates hidden until everyone is ready.'}</p></div><span class="direction-label">OLDEST <span>→</span> NEWEST</span></div><div class="timeline-track" aria-hidden="true"><span>BEFORE</span><i></i><span>AFTER</span></div><div class="hand-grid">${hand.map((id,i)=>timelineCard(id,i,revealed,solution)).join('')}</div>${revealed?`<div class="result-strip" role="status"><div><span class="result-score">${result}<small>/5</small></span><div><h3>Cards in the correct position</h3><p>${solution?'The cards now show the correct order.':'Your first check is saved. Review the order and read the Spanish on each card.'}</p></div></div><div class="result-actions"><button class="secondary" data-action="solution">Show correct order</button><button class="primary" data-action="next-player">${allDone?'View scores':'Next player'} →</button></div></div>`:`<div class="board-bottom"><p lang="es">«Creo que <strong>…</strong> apareció antes que <strong>…</strong>»<br><span class="small-note">Say your order in Spanish, then check it.</span></p><button class="primary" data-action="check">Check my order <span>→</span></button></div>`}<div class="game-note"><span>${revealed?'Scores are recorded from the first attempt.':'1 point per card in the correct position. Maximum: 5.'}</span><button class="text-link" data-action="restart">Restart this deal</button></div></section>`;
}
function renderGuess(){
  const g=session.guess[config.seat],done=g.index>=5,guesser=(config.seat+1)%config.players;
  if(done){$('#app').innerHTML=`<section class="game-view">${gameHeader()}<div class="complete-panel"><span class="eyebrow">FIVE CLUES READ</span><h2>Player ${config.seat+1}’s hand is complete.</h2><p>Player ${guesser+1} guessed ${g.marks.filter(Boolean).length} out of 5.</p><div class="mini-card-row">${session.orders[config.seat].map((id,i)=>`<button data-detail="${id}">${illustration(id)}<span lang="es">${esc(lookup(id).title)}</span><small>${g.marks[i]?'Correct':'Passed'}</small></button>`).join('')}</div><button class="primary" data-action="next-player">${session.guess.every(x=>x.index===5)?'View scores':'Next reader'} →</button></div><div class="game-note"><span>Correct answers count for the guesser.</span><button class="text-link" data-action="restart">Restart this deal</button></div></section>`;return;}
  const e=lookup(session.orders[config.seat][g.index]);
  $('#app').innerHTML=`<section class="game-view">${gameHeader()}<div class="guess-layout"><aside class="guess-side"><span class="eyebrow">THE ROLES</span><div class="role-line"><span class="player-dot">${config.seat+1}</span><div><strong>Player ${config.seat+1}</strong><small>Reads the clue</small></div></div><div class="role-line"><span class="player-dot coral">${guesser+1}</span><div><strong>Player ${guesser+1}</strong><small>Guesses the invention</small></div></div><p>Keep this screen facing the reader. Read or paraphrase the Spanish clue. The other player answers aloud.</p><div class="guess-progress" aria-label="Clue ${g.index+1} of 5">${Array.from({length:5},(_,i)=>`<span class="${i<g.index?'done':i===g.index?'current':''}">${i<g.index?'✓':i+1}</span>`).join('')}</div></aside><div class="clue-card"><div class="clue-top"><span class="micro">CLUE ${String(g.index+1).padStart(2,'0')} / 05</span><span>READ ALOUD</span></div><span class="quote-mark" aria-hidden="true">“</span><p class="clue-text" lang="es">${esc(e.before)}</p><div id="guess-answer"><div class="answer-hidden"><span>What invention or discovery is it?</span><button class="primary" data-action="reveal">Reveal the answer <span>→</span></button></div></div></div></div><div class="game-note"><span>No timer. Give the other player time to answer.</span><button class="text-link" data-action="restart">Restart this deal</button></div></section>`;
}
function revealGuess(){const g=session.guess[config.seat];if(g.index>=5)return;const e=lookup(session.orders[config.seat][g.index]);$('#guess-answer').innerHTML=`<div class="guess-reveal"><div class="guess-reveal-art">${illustration(e.id)}</div><div><span class="eyebrow">THE ANSWER</span><h2 lang="es">${esc(e.title)}</h2><div class="date-block" lang="es"><strong>${yearLabel(e.year)}</strong><span>${esc(e.approx)}</span></div><p lang="es">${esc(e.after)}</p><button class="text-link" data-detail="${e.id}">Read the full story ↗</button></div></div><div class="guess-mark"><span>Did Player ${(config.seat+1)%config.players+1} guess it?</span><div><button class="secondary" data-mark="0">Pass</button><button class="primary" data-mark="1">Correct ✓</button></div></div>`;}
function handoff(seat){modal(`<p class="eyebrow">PASS THE DEVICE</p><h2>Player ${seat+1}, your turn.</h2><p>${config.mode==='guess'?'Keep the screen facing you. The next player will guess your clues.':'The next screen will show your five cards.'}</p><button class="primary wide" data-ready="${seat}">I’m Player ${seat+1} →</button>`);}
function scoreboard(){let scores;if(config.mode==='timeline')scores=Array.from({length:config.players},(_,i)=>session.results[i]??null);else scores=Array.from({length:config.players},(_,i)=>{const reader=(i+config.players-1)%config.players;return session.guess[reader].index===5?session.guess[reader].marks.filter(Boolean).length:null;});const done=scores.every(s=>s!==null),best=Math.max(...scores.filter(s=>s!==null));const leaders=scores.map((s,i)=>s===best?i+1:null).filter(Boolean);modal(`<p class="eyebrow">GAME ${config.code} / ${config.mode==='guess'?'DESCRIBE & GUESS':'TIMELINE'}</p><h2>${!done?'Scores on this device':leaders.length>1?'It’s a draw.':`Player ${leaders[0]} has the highest score.`}</h2><div class="score-list">${scores.map((s,i)=>`<div><span>Player ${i+1}</span><strong>${s===null?'—':`${s}<small> / 5</small>`}</strong></div>`).join('')}</div><p class="small-note">If you are using separate devices, compare your scores aloud. Only hands completed here appear in this list.</p><button class="primary wide" data-action="new-code">Play another deal →</button>`);}
function library(){screen='library';const categories=['All',...new Set(EVENTS.map(e=>e.category))];$('#app').innerHTML=`<section class="library"><div class="library-heading"><div><p class="eyebrow">THE COMPLETE DECK / ${EVENTS.length} CARDS</p><h1>The card library</h1><p>Inventions, discoveries and the things they changed.</p></div><button class="secondary" data-action="setup">Back to game setup →</button></div><div class="library-controls"><label class="search-label"><span aria-hidden="true">⌕</span><input id="library-search" type="search" placeholder="Find a milestone…" value="${esc(libraryQuery)}" aria-label="Search cards"></label><div class="filter-row">${categories.map(c=>`<button data-category="${esc(c)}" class="${category===c?'active':''}" aria-pressed="${category===c}">${esc(c)}</button>`).join('')}</div></div><p class="library-spoiler">The library shows dates. Browse after your game if you want to keep them hidden.</p><div class="library-grid" id="library-grid"></div></section>`;renderLibraryCards();}
function renderLibraryCards(){const q=libraryQuery.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const cards=sorted(EVENTS).filter(e=>(category==='All'||e.category===category)&&`${e.title} ${e.person}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));$('#library-grid').innerHTML=cards.length?cards.map(e=>`<button class="library-card" data-detail="${e.id}"><div class="library-art">${illustration(e.id)}</div><div><span class="card-category">${esc(e.category)}</span><h3 lang="es">${esc(e.title)}</h3><strong class="library-year" lang="es">${yearLabel(e.year)}</strong><span class="library-approx" lang="es">${esc(e.approx)}</span><span class="library-read">Read the story ↗</span></div></button>`).join(''):'<p class="empty-state">No cards match your search.</p>';}

document.addEventListener('input',e=>{if(e.target.id==='library-search'){libraryQuery=e.target.value;renderLibraryCards();}if(e.target.id==='game-code'){$('#code-error').textContent='';}});
document.addEventListener('click',async e=>{
  const b=e.target.closest('button,a.brand');if(!b)return;
  if(b.matches('a.brand')){e.preventDefault();setup();return;}
  if(b.dataset.nav){if(b.dataset.nav==='help'){showHelp();return;}document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n===b));if(b.dataset.nav==='library')library();else setup();window.scrollTo(0,0);return;}
  if(b.dataset.mode){if(!readConfig())return;config.mode=b.dataset.mode;setup();}
  if(b.dataset.players){if(!readConfig())return;config.players=Number(b.dataset.players);config.seat=Math.min(config.seat,config.players-1);setup();}
  if(b.dataset.seat){if(!readConfig())return;config.seat=Number(b.dataset.seat);setup();}
  if(b.dataset.switch!==undefined){if(Number(b.dataset.switch)!==config.seat)handoff(Number(b.dataset.switch));}
  if(b.dataset.ready!==undefined){config.seat=Number(b.dataset.ready);$('#modal').close();renderGame();window.scrollTo(0,0);}
  if(b.dataset.move){const [from,to]=b.dataset.move.split(',').map(Number);session.orders[config.seat]=moveCard(session.orders[config.seat],from,to);persist();renderGame();const focus=document.querySelector(`[data-card-index="${to}"] [data-move]`);focus?.focus();}
  if(b.dataset.detail)cardDetail(b.dataset.detail);
  if(b.dataset.category){category=b.dataset.category;library();}
  if(b.dataset.mark!==undefined){const g=session.guess[config.seat];g.marks.push(b.dataset.mark==='1');g.index++;persist();renderGuess();}
  const action=b.dataset.action;
  if(action==='setup')setup();
  if(action==='language')languageHelp();
  if(action==='start')start();
  if(action==='random'){config.code=String(crypto.getRandomValues(new Uint32Array(1))[0]%100+1).padStart(3,'0');setup();}
  if(action==='close-modal')$('#modal').close();
  if(action==='check'){if(session.results[config.seat]===undefined){session.results[config.seat]=scoreOrder(session.orders[config.seat].map(lookup));persist();}renderGame();}
  if(action==='solution'){session.orders[config.seat]=sorted(session.orders[config.seat].map(lookup)).map(c=>c.id);persist();renderGame(true);}
  if(action==='next-player'){const next=Array.from({length:config.players},(_,i)=>(config.seat+1+i)%config.players).find(i=>config.mode==='timeline'?session.results[i]===undefined:session.guess[i].index<5);if(next===undefined)scoreboard();else handoff(next);}
  if(action==='reveal')revealGuess();
  if(action==='restart'){modal(`<p class="eyebrow">RESTART GAME ${config.code}</p><h2>Deal these cards again?</h2><p>This clears the moves and scores for all players in this mode on this device. The same code deals the same cards.</p><div class="dialog-actions"><button class="secondary" data-action="close-modal">Keep playing</button><button class="primary" data-action="confirm-restart">Restart deal</button></div>`);}
  if(action==='confirm-restart'){session=newSession();persist();$('#modal').close();renderGame();}
  if(action==='new-code'){config.code=String(Number(config.code)%100+1).padStart(3,'0');$('#modal').close();setup();}
  if(action==='share'){const url=new URL(location.href);url.search=new URLSearchParams({game:config.code,players:config.players,mode:config.mode});try{await navigator.clipboard.writeText(url.href);toast('Game link copied. Each player chooses a different player number.');}catch{modal(`<h2>Share this game</h2><p>Use game ${config.code}, ${config.players} players and ${config.mode==='timeline'?'Put it in order':'Describe & guess'}.</p><input class="share-input" value="${esc(url.href)}" readonly aria-label="Game link">`);}}
});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-card-index]');if(!card||session.results[config.seat]!==undefined)return;dragFrom=Number(card.dataset.cardIndex);e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragFrom));card.classList.add('dragging');});
document.addEventListener('dragover',e=>{if(dragFrom===null)return;const card=e.target.closest('[data-card-index]');if(card){e.preventDefault();e.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',e=>{const card=e.target.closest('[data-card-index]');if(dragFrom===null||!card)return;e.preventDefault();session.orders[config.seat]=moveCard(session.orders[config.seat],dragFrom,Number(card.dataset.cardIndex));dragFrom=null;persist();renderGame();});
document.addEventListener('dragend',()=>{dragFrom=null;document.querySelectorAll('.dragging').forEach(c=>c.classList.remove('dragging'));});
$('.modal-close').addEventListener('click',()=>$('#modal').close());
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('#modal').close();}});
$('#date-note').addEventListener('click',dateHelp);
setup();
